def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    color = 7
    runs_by_row = []
    for r, row in enumerate(grid):
        runs = []
        c = 0
        while c < w:
            if row[c] == color:
                start = c
                while c + 1 < w and row[c + 1] == color:
                    c += 1
                runs.append((start, c))
            c += 1
        runs_by_row.append(runs)

    best = None
    for r1 in range(h):
        for r2 in range(r1 + 1, h):
            for a, b in runs_by_row[r1]:
                for c, d in runs_by_row[r2]:
                    if a == c and b != d:
                        short_r, short_end, long_end = (
                            (r1, b, d) if b < d else (r2, d, b)
                        )
                        if all(grid[short_r][x] == grid[short_r][0] or grid[short_r][x] != color
                               for x in range(short_end + 1, long_end + 1)):
                            length = long_end - short_end
                            if best is None or length > best[0]:
                                best = (length, short_r, short_end, long_end)

    if best:
        _, r, end, long_end = best
        for c in range(end + 1, long_end + 1):
            if grid[r][c] != color:
                out[r][c] = 1
    return out
